for(const [lang,values] of Object.entries(extraTranslations))Object.assign(translations[lang],values);
let session=null,ready=false,pending=false,events=[];
async function apiCall(path,method='GET',value){
 let response;try{response=await fetch(path,{method,credentials:'same-origin',headers:{...(value!==undefined?{'Content-Type':'application/json'}:{})},...(value!==undefined?{body:JSON.stringify(value)}:{})})}catch{throw {code:'networkError'}}
 let data;try{data=await response.json()}catch{throw {code:'unavailable'}}
 if(!response.ok)throw {code:data.error?.code||'unavailable',status:response.status};return data;
}
async function refreshData(){const [nextState,nextAudit]=await Promise.all([apiCall('/api/state'),apiCall('/api/audit')]);db=nextState;events=nextAudit.events;ready=true;render();}
function syncBanner(message,error=false){const banner=$('#sync-banner');banner.textContent=message;banner.className=error?'sync-banner error':'sync-banner';}
async function boot(){
 updateChrome();syncBanner(t('loading'));$('#view').innerHTML=`<div class="empty">${t('loading')}</div>`;$('#add').disabled=true;
 try{session=(await apiCall('/api/session')).user;await refreshData();$('#add').disabled=false;}
 catch(error){ready=false;$('#view').innerHTML=`<div class="empty"><p>${t(error.code||'unavailable')}</p><br>${error.status===401?`<a class="button-link" href="/signin-with-chatgpt?return_to=%2F" target="_top">${t('signIn')}</a>`:`<button onclick="boot()">${t('retry')}</button>`}</div>`;syncBanner(t(error.code||'unavailable'),true)}
}
async function mutate(form,path,method,value,message){
 if(pending)return;pending=true;const button=form?.querySelector('button.primary');if(button)button.disabled=true;
 try{await apiCall(path,method,value);closeModal();await refreshData();syncBanner(t('ready'));toast(t(message));}
 catch(error){toast(t(error.code||'unavailable'));if(error.status===409){closeModal();await refreshData().catch(()=>syncBanner(t('networkError'),true))}else syncBanner(t(error.code||'networkError'),true)}
 finally{pending=false;if(button)button.disabled=false}
}
function archiveRecord(resource,id,restore=false){const record=db[resource].find(x=>x.id===id);modal(`<h2>${t(restore?'restore':'archive')}</h2><p class="help-copy">${t(restore?'confirmRestore':'confirmArchive')}</p><form id="archiveForm">${buttons(restore?'restore':'archive')}</form>`);$('#archiveForm').onsubmit=e=>{e.preventDefault();mutate(e.target,`/api/${resource}/${id}/${restore?'restore':'archive'}`,'POST',{version:record.version},restore?'restoredToast':'archivedToast')}}
function activity(){$('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>${t('activity')}</h2></div><p class="note">${t('auditNote')}</p><div class="table-wrap"><table>${headings(['when','actions','entity','entityId'])}<tbody>${events.map(e=>`<tr><td>${esc(new Date(e.at).toLocaleString(locale()))}</td><td>${t('audit_'+e.action)}</td><td>${t('entity_'+e.entity)}</td><td>${esc(e.entity_id)}</td></tr>`).join('')||empty('noAudit',4)}</tbody></table></div></div>`}
function settings(){$('#view').innerHTML=`<div class="panel settings"><h2>${t('settings')}</h2><p class="help-copy">${t('storageHelp')}</p><dl><dt>${t('account')}</dt><dd>${esc(session?.email||session?.id||'')}</dd><dt>${t('status')}</dt><dd>${t('ownerRole')}</dd></dl><div class="actions"><button onclick="exportData()">${t('export')}</button><button onclick="refreshData().catch(()=>toast(t('networkError')))">${t('sync')}</button><a class="button-link" href="/signout-with-chatgpt?return_to=%2F" target="_top">${t('signOut')}</a></div><hr><h2>${t('importData')}</h2><p class="help-copy">${t('importWarning')}</p><div class="actions"><button onclick="$('#importFile').click()">${t('importData')}</button><input id="importFile" type="file" accept="application/json,.json" hidden onchange="importFile(this)"><button onclick="importLocal()">${t('importLocal')}</button><button onclick="importDemo()">${t('importDemo')}</button></div></div>`}
function confirmImport(data){if(!data||!['books','readers','loans'].every(key=>Array.isArray(data[key])))return toast(t('invalidData'));modal(`<h2>${t('importData')}</h2><p class="help-copy">${t('confirmImport')}</p><p class="help-copy">${t('bookPaging',{count:data.books.length,page:1,max:1})} · ${t('readerCount',{count:data.readers.length})} · ${t('loanCount',{count:data.loans.length})}</p><form id="importForm">${buttons('importData')}</form>`);$('#importForm').onsubmit=e=>{e.preventDefault();mutate(e.target,'/api/import','POST',data,'imported')}}
async function importFile(input){const file=input.files[0];if(!file)return;if(file.size>2_000_000)return toast(t('tooLarge'));try{confirmImport(JSON.parse(await file.text()))}catch{toast(t('invalidData'))}finally{input.value=''}}
function importLocal(){try{const data=JSON.parse(localStorage.getItem('folio-v1'));if(!data)return toast(t('noLocal'));confirmImport(data)}catch{toast(t('invalidData'))}}
function importDemo(){const books=seeds.map((b,i)=>({id:uid(),title:b[0],author:b[1],category:b[2],color:b[3],isbn:'DEMO-'+String(i+1).padStart(5,'0'),shelf:`A1-${i+1}`}));confirmImport({books,readers:[{id:uid(),name:'Demo Reader',card:'R001',email:'reader@example.com'}],loans:[]})}
